"""v165: migrate a synthetic canonical save generated by the ACTUAL signed v124 APK.

Fixture provenance: user-installed v124 Build #302 APK SHA256
8ad2d0907a61f3455c80eae0ec73bb6b98617f72d11227dc9d32e25d39ac5fc7.
Separate local two-APK browser test also proved exact v124 downgrade drops the
new markers and independent exported JSON restores them. No user save is used.
"""
from pathlib import Path
from playwright.sync_api import sync_playwright
import hashlib, json, shutil
R=Path(__file__).resolve().parent
A=R/'app/src/main/assets'
KEY='bf_global_offline_demo_v7'
raw=(R/'source_data/bf165_real_signed_v124_first_clear_save.json').read_text('utf8').rstrip('\n')
assert hashlib.sha256(raw.encode()).hexdigest()=='503165ae5b5f476a92f8a0e9f4d2197b8e2aa41a3a3462d23e1e202bec953170'
fixture=json.loads(raw)
assert fixture['version']==7 and fixture['questClears']=={'12':1}
assert len(fixture['roster'])==6 and len(fixture['squad'])==6
assert '_bfGemV160' not in fixture and '_bfGemV161Pending' not in fixture
html=(A/'index.html').read_text('utf8')
qol=(A/'bf9700_qol_rotating_backups.js').read_text('utf8')
assert 'BF_GLOBAL_GEM_V160_ORIGINAL_CLEAR_LEDGER' in html
assert 'BF_GLOBAL_GEM_V161_NEW_FIRST_CLEAR_PENDING' in html
assert 'bf9700-export-current' in qol and 'EXPORT CURRENT SAVE' in qol

with sync_playwright() as pw:
 browser=pw.chromium.launch(headless=True,
  executable_path=shutil.which('chromium') or shutil.which('google-chrome') or shutil.which('google-chrome-stable'),
  args=['--no-sandbox','--disable-dev-shm-usage'])
 p=browser.new_page(viewport={'width':390,'height':844})
 errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
 p.evaluate("""()=>{const db={};window.__v165writes=[];
  Object.defineProperty(window,'localStorage',{configurable:true,value:{
   getItem:k=>db[k]??null,setItem:(k,v)=>{db[k]=String(v);__v165writes.push(k)},
   removeItem:k=>{delete db[k];__v165writes.push(k)},
   key:i=>Object.keys(db)[i]??null,get length(){return Object.keys(db).length}}});
  window.alert=()=>{};window.confirm=()=>true;
  HTMLMediaElement.prototype.load=()=>{};
  HTMLMediaElement.prototype.pause=()=>{};
  HTMLMediaElement.prototype.play=()=>Promise.resolve();
 }""")
 p.set_content(html,wait_until='load',timeout=90000)
 assert p.evaluate('P.version')==7
 p.evaluate('raw=>{P=parseProgress(JSON.parse(raw))}',raw)
 state=p.evaluate("""()=>({
  version:P.version,roster:P.roster,squad:P.squad,clears:P.questClears,
  legacy:P._bfGemV160.legacyFinales,pending:P._bfGemV161Pending,
  balance:P._bfGemV160.balance,paid:P._bfGemV160.paidFinales
 })""")
 assert state=={'version':7,'roster':fixture['roster'],'squad':fixture['squad'],
   'clears':{'12':1},'legacy':[12],'pending':[],'balance':0,'paid':[]},state
 assert p.evaluate('saveProgress()') is True
 assert set(p.evaluate('__v165writes'))=={KEY}
 # Already-cleared v124 finales must not retroactively earn new claims.
 p.evaluate('QUEST=QUESTS.find(q=>q.missionId===12);awardDemoRewards()')
 assert p.evaluate('P.questClears[12]')==2
 assert p.evaluate('P._bfGemV161Pending')==[]
 # A new source-confirmed first-clear is recorded exactly once.
 p.evaluate('QUEST=QUESTS.find(q=>q.missionId===23);awardDemoRewards()')
 p.evaluate('awardDemoRewards()')
 assert p.evaluate('P._bfGemV161Pending')==[23]
 assert p.evaluate('P._bfGemV160.legacyFinales')==[12,23]
 assert p.evaluate('P._bfGemV160.balance')==0
 assert p.evaluate('P._bfGemV160.paidFinales')==[]
 exact=p.evaluate("localStorage.getItem('bf_global_offline_demo_v7')")
 p.evaluate("""()=>{window.__v165export=null;
  window.BFAndroid={exportSaveFile:(raw,name)=>{window.__v165export={raw,name}}};}""")
 p.add_script_tag(content=qol)
 assert p.locator('#bf9700-backups').count()==1
 p.locator('#bf9700-backups summary').click()
 p.locator('#bf9700-export-current').click()
 export=p.evaluate('__v165export')
 assert export and export['raw']==exact
 assert export['name'].startswith('BraveFrontier-v7-current-')
 assert json.loads(export['raw'])['_bfGemV161Pending']==[23]
 assert p.evaluate("localStorage.getItem('bf_global_offline_demo_v7')")==exact
 assert p.evaluate('P._bfGemV160.balance')==0
 assert not errors,errors
 browser.close()
print('PASS v165: real signed v124 synthetic save migrated, legacy not re-awarded, new first-clear once, byte-exact current export, v7 save protected and zero Gem payouts')
